VectorIntrinsic vi2 = CreateVectorIntrinsic(1.0f, 2.0f, 3.0f, 4.0f);
VectorIntrinsic vi3 = CreateVectorIntrinsic(11.0f, 12.0f, 13.0f, 14.0f);
VectorIntrinsic result;
RW_MATH_VPU_MultAdd(result, vi1, vi2, vi3);
VectorIntrinsic ref = CreateVectorIntrinsic( 42.0f+11.0f, 43.0f*2.0f+12.0f, 44.0f*3.0f+13.0f, 45.0f*4.0f+14.0f );
VectorIntrinsic t = CreateVectorIntrinsic( 0.0001f, 0.0001f, 0.0001f, 0.0001f );

Validate( _asmIsSimilarV4( ref, result, t ) );



