SetFunctionName("_asmIsEqualV4(VectorIntrinsic_InParam v0,   VectorIntrinsic_InParam v1)");
VectorIntrinsic vi1 = CreateVectorIntrinsic(1.0f, 2.0f, 3.0f, 4.0f);
VectorIntrinsic vi2 = CreateVectorIntrinsic(1.0f, 2.0f, 3.0f, 4.0f);
VectorIntrinsic vi3 = CreateVectorIntrinsic(1.0f, 2.0f, 3.0f, 4.1f);

Validate(
         _asmIsEqualV4( vi1, vi2 ) &&
         _asmIsEqualV4( vi2, vi1 ) &&
        !_asmIsEqualV4( vi1, vi3 ) &&
        !_asmIsEqualV4( vi1, vi3 ) &&
        !_asmIsEqualV4( vi3, vi2 )
    );



SetFunctionName("_asmIsEqualV3(VectorIntrinsic_InParam v0,   VectorIntrinsic_InParam v1)");
VectorIntrinsic vi1 = CreateVectorIntrinsic(1.0f, 2.0f, 3.0f, 4.0f);
VectorIntrinsic vi2 = CreateVectorIntrinsic(1.0f, 2.0f, 3.0f, 4.0f);
VectorIntrinsic vi3 = CreateVectorIntrinsic(1.0f, 2.0f, 3.0f, 4.1f);
VectorIntrinsic vi4 = CreateVectorIntrinsic(1.0f, 2.0f, 3.1f, 4.1f);

Validate(
         _asmIsEqualV3( vi1, vi2 ) &&
         _asmIsEqualV3( vi2, vi1 ) &&
         _asmIsEqualV3( vi1, vi3 ) &&
         _asmIsEqualV3( vi1, vi3 ) &&
         _asmIsEqualV3( vi3, vi2 ) &&
        !_asmIsEqualV3( vi1, vi4 ) &&
        !_asmIsEqualV3( vi3, vi4 ) &&
        !_asmIsEqualV3( vi4, vi1 ) &&
        !_asmIsEqualV3( vi4, vi3 )
    );



SetFunctionName("RW_MATH_VPU_Splat_I(r, v, i)");
VectorIntrinsic vi = CreateVectorIntrinsic(1.0f, 2.0f, 3.0f, 4.0f);
VectorIntrinsic res1;
RW_MATH_VPU_Splat_I(res1, vi, VectorAxisX);
VectorIntrinsic res2;
RW_MATH_VPU_Splat_I(res2, vi, VectorAxisY);
VectorIntrinsic res3;
RW_MATH_VPU_Splat_I(res3, vi, VectorAxisZ);
VectorIntrinsic res4;
RW_MATH_VPU_Splat_I(res4, vi, VectorAxisW);

VectorIntrinsic ref1 = RW_MATH_VPU_CreateVectorFromScalar_R(1.0f);
VectorIntrinsic ref2 = RW_MATH_VPU_CreateVectorFromScalar_R(2.0f);
VectorIntrinsic ref3 = RW_MATH_VPU_CreateVectorFromScalar_R(3.0f);
VectorIntrinsic ref4 = RW_MATH_VPU_CreateVectorFromScalar_R(4.0f);

Validate(
    _asmIsEqualV4(res1, ref1) &&
    _asmIsEqualV4(res2, ref2) &&
    _asmIsEqualV4(res3, ref3) &&
    _asmIsEqualV4(res4, ref4)
    );



