    );



SetFunctionName("template<VectorAxis INDEX_DEST, VectorAxis INDEX_SRC> VectorIntrinsic _asmSwizzleStore(VectorIntrinsic_InParam dest, VectorIntrinsic_InParam src)");
VectorIntrinsic vi1 = CreateVectorIntrinsic(1.0f, 2.0f, 3.0f, 4.0f);
VectorIntrinsic vi2 = CreateVectorIntrinsic(10.0f, 20.0f, 30.0f, 40.0f);

VectorIntrinsic res[16];
res[0]  = _asmSwizzleStore<VectorAxisX, VectorAxisX>(vi1, vi2);
res[1]  = _asmSwizzleStore<VectorAxisX, VectorAxisY>(vi1, vi2);
res[2]  = _asmSwizzleStore<VectorAxisX, VectorAxisZ>(vi1, vi2);
res[3]  = _asmSwizzleStore<VectorAxisX, VectorAxisW>(vi1, vi2);
res[4]  = _asmSwizzleStore<VectorAxisY, VectorAxisX>(vi1, vi2);
res[5]  = _asmSwizzleStore<VectorAxisY, VectorAxisY>(vi1, vi2);
res[6]  = _asmSwizzleStore<VectorAxisY, VectorAxisZ>(vi1, vi2);
res[7]  = _asmSwizzleStore<VectorAxisY, VectorAxisW>(vi1, vi2);
res[8]  = _asmSwizzleStore<VectorAxisZ, VectorAxisX>(vi1, vi2);
res[9]  = _asmSwizzleStore<VectorAxisZ, VectorAxisY>(vi1, vi2);
res[10] = _asmSwizzleStore<VectorAxisZ, VectorAxisZ>(vi1, vi2);
res[11] = _asmSwizzleStore<VectorAxisZ, VectorAxisW>(vi1, vi2);
res[12] = _asmSwizzleStore<VectorAxisW, VectorAxisX>(vi1, vi2);
res[13] = _asmSwizzleStore<VectorAxisW, VectorAxisY>(vi1, vi2);
res[14] = _asmSwizzleStore<VectorAxisW, VectorAxisZ>(vi1, vi2);
res[15] = _asmSwizzleStore<VectorAxisW, VectorAxisW>(vi1, vi2);

bool success = true;
for( int i=0; i<16; ++i)
{
    float refArray[] = { 1.0f, 2.0f, 3.0f, 4.0f };
    float srcArray[] = { 10.0f, 20.0f, 30.0f, 40.0f };
    refArray[i/4] = srcArray[i%4];
    VectorIntrinsic ref = CreateVectorIntrinsic( refArray[0], refArray[1], refArray[2], refArray[3] );
    if( !_asmIsEqualV4( ref, res[i] ) )
    {
        const char *axisStrings[] = { "VectorAxisX", "VectorAxisY", "VectorAxisZ", "VectorAxisW" };
        SetFunctionName("template<VectorAxis %s, VectorAxis %s> VectorIntrinsic _asmSwizzleStore(VectorIntrinsic_InParam dest, VectorIntrinsic_InParam src)", axisStrings[i/4], axisStrings[i%4] );
        success = false;
        break;
    }
}
Validate(success);



SetFunctionName("template<VectorAxis INDEX_DEST> VectorIntrinsic _asmSwizzleStore(VectorIntrinsic_InParam dest, VectorIntrinsic_InParam src, int srcIndex)");
VectorIntrinsic vi1 = CreateVectorIntrinsic(1.0f, 2.0f, 3.0f, 4.0f);
VectorIntrinsic vi2 = CreateVectorIntrinsic(10.0f, 20.0f, 30.0f, 40.0f);

VectorIntrinsic res[16];
res[ 0] = _asmSwizzleStore<VectorAxisX>(vi1, vi2, VectorAxisX);
