b.scalarUInt[2] = 0x10101010;
b.scalarUInt[3] = 0x01010101;

ref.scalarUInt[0] = 0xF0F0F0F0;
ref.scalarUInt[1] = 0x0F0F0F0F;
ref.scalarUInt[2] = 0x10101010;
ref.scalarUInt[3] = 0x01010101;

